// Hand-curated "the story of…" / "the … chapter" map for the quick-find: things an
// operator names that aren't in the verse text ("prodigal son" never appears in the KJV).
// Matched in the renderer — static data, no IPC. Titles are display strings; aliases are
// extra ways people say it. Ranges are validated against the bundled KJV in passages.test.
//
// A story lists EVERY place it is told: the resurrection is four gospel accounts, the
// Last Supper is four plus Paul's. Each account is its own result row (same title, its own
// reference), so Enter / + Add / Shift+Enter work on one reference exactly as before and
// the operator picks the gospel the pastor is reading from. Refs are written in the order
// they should list — canonical, except where one account is the one people mean (the
// Christmas story is Luke 2 before Matthew 1).
import { norm, textSignals } from '../search/fuzzy'
import { parseVerseQuery } from '../search/verseScore'
import { modernWord } from '../search/wording'
import { canonicalBookIndex } from './books'

export interface PassageRef { book: string; ch: number; from: number; to: number }
export interface Story { title: string; aliases: string[]; refs: PassageRef[] }
/** One result row: a story at one of the places it is told. */
export interface Passage extends PassageRef { title: string }

/** `'Matthew 28:1-10; Mark 16:1-8'` → refs. One chapter per ref (a ParsedRef is one
 * chapter); a story that runs across chapters lists each chapter as its own ref. */
function parseRefs(spec: string): PassageRef[] {
  return spec.split(';').map((part) => {
    const m = part.trim().match(/^(.+) (\d+):(\d+)(?:-(\d+))?$/)
    if (!m) throw new Error(`passages: bad reference "${part}"`)
    const from = Number(m[3])
    return { book: m[1], ch: Number(m[2]), from, to: m[4] ? Number(m[4]) : from }
  })
}

const S = (title: string, refs: string, ...aliases: string[]): Story => ({ title, aliases, refs: parseRefs(refs) })

