// Words that carry no story: an operator says "the resurrection of Jesus" or "the parable
// of the sower" and means "resurrection" / "sower". They are dropped from BOTH the query
// and the index for the match itself, so "jesus turns water into wine" needs only
// turns/water/wine. A query made of nothing else ("jesus", "parable") falls back to the
// full text. "lord" is deliberately absent — "lords prayer", "lords supper" turn on it.
const FILLER = new Set([
  'the', 'a', 'an', 'of', 'and', 'in', 'on', 'at', 'to', 'for', 'with', 'from', 'by', 'into', 'unto', 'upon',
  'is', 'are', 'was', 'be', 'that', 'this', 'his', 'her', 'their', 'my', 'our', 'your', 'thy',
  'i', 'he', 'she', 'it', 'we', 'you', 'ye', 'they', 'when', 'where', 'who', 'about',
  'jesus', 'christ', 'story', 'parable',
])

interface Indexed { s: Story; full: string[][]; core: string[][]; order: [number, number, number] }
// Title and each alias are separate segments: a phrase run can't bridge "lost sheep" +
// "lost coin" into a 3-word match. `core` is the same with the filler words removed.
const INDEX: Indexed[] = STORIES.map((s) => {
  // Modern spelling on both sides (wording.ts), as in verse search: the aliases quote the
  // KJV ("whither thou goest"), the operator may not.
  const full = [s.title, ...s.aliases].map((t) => norm(t).split(' ').filter(Boolean).map(modernWord))
  const core = full.map((seg) => seg.filter((w) => !FILLER.has(w))).filter((seg) => seg.length > 0)
  const r = s.refs[0]
  return { s, full, core, order: [canonicalBookIndex(r.book), r.ch, r.from] }
})

/** Max result rows. Enough for the longest story (every account of it) plus a neighbour
 * or two; the verse hits list under these, so this is not the place to be exhaustive. */
export const PASSAGE_ROWS = 8

/** What a missing word costs, in match-distance units (exact 0, prefix 1, typo 1–2 per
 * word). Above any honest all-words match — two typos and a half-typed last word is 3 — so
 * a story that holds every word wins; below a match made of nothing but typos — "heals ten
 * lepers" is not Peter's Confession by way of hell/men/peters. */
const MISS_COST = 3.5

/** Stories for a query, one row per place the story is told.
 *
 * Every word that carries meaning must match (prefix/fuzzy, same rules as verse search);
 * filler words ("the", "of", "jesus", "parable"…) never gate. A query of three or more
 * meaningful words may miss one of them, at a price (MISS_COST) — "jesus heals ten lepers"
 * finds The Ten Lepers although no title says "heals".
 *
 * Only the cheapest tier survives — a closer match hides fuzzier ones: 'zacch' is
 * Zacchaeus, not Gethsemane via 'watch'. Then order by the phrase run of the query AS
 * TYPED ↓ ("my lord and my god" is Thomas, not every title holding "lord" and "god"),
 * phrase run of the meaningful words ↓, matched weight ↓, named in the title before named
 * only in an alias, title length ↑, then canonical ↑
 * so the table's order never leaks into the result. Stories then flatten to rows in that
 * order — a story's accounts stay together, in the order the table lists them. */
export function matchPassages(q: string, limit = PASSAGE_ROWS): Passage[] {
  const tokens = parseVerseQuery(q).tokens.map(modernWord)
  if (!tokens.length) return []
  const meaningful = tokens.filter((t) => !FILLER.has(t))
  const useCore = meaningful.length > 0
  const qts = useCore ? meaningful : tokens
  const scored = INDEX.map((ix) => ({ ix, s: textSignals(useCore ? ix.core : ix.full, qts) }))
  const allowMiss = qts.length >= 3 ? 1 : 0
  const pool = scored
    .filter((x) => x.s.matched >= qts.length - allowMiss)
    .map((x) => ({ ...x, cost: x.s.dist + (qts.length - x.s.matched) * MISS_COST }))
  const minCost = pool.reduce((m, x) => Math.min(m, x.cost), Infinity)
  const stripped = qts.length < tokens.length
  return pool
    .filter((x) => x.cost === minCost)
    .map((x) => ({
      ...x,
      typed: stripped ? textSignals(x.ix.full, tokens).phrase : x.s.phrase,
      // Named in the TITLE, not only in an alias: "lost" is The Lost Sheep before it is
      // Zacchaeus ("…to save that which was lost").
      titled: textSignals([x.ix.full[0]], qts).matched === qts.length ? 1 : 0,
    }))
    .sort((a, b) => {
      if (b.typed !== a.typed) return b.typed - a.typed
      if (b.s.phrase !== a.s.phrase) return b.s.phrase - a.s.phrase
      if (b.s.covWeight !== a.s.covWeight) return b.s.covWeight - a.s.covWeight
      if (b.titled !== a.titled) return b.titled - a.titled
      if (a.ix.s.title.length !== b.ix.s.title.length) return a.ix.s.title.length - b.ix.s.title.length
      for (let i = 0; i < 3; i++) if (a.ix.order[i] !== b.ix.order[i]) return a.ix.order[i] - b.ix.order[i]
      return 0
    })
    .flatMap((x) => x.ix.s.refs.map((r) => ({ title: x.ix.s.title, ...r })))
    .slice(0, limit)
}
